example.code:
LZ4Codec.Encode(data, out BufferLease lease, out int written);
using (lease)
{
    Send(lease.Span); // zero-copy handoff
}

LZ4Codec.Decode(compressed, out BufferLease lease, out int written);
using (lease)
{
    Process(lease.Span); // zero-copy
}

// AEAD example (CHACHA20-Poly1305)
var ct = EnvelopeCipher.Encrypt(key32, data, CipherSuiteType.CHACHA20_POLY1305, aad);

// Stream/CTR example (CHACHA20)
var ct2 = EnvelopeCipher.Encrypt(key32, data, CipherSuiteType.CHACHA20);

// AEAD example (CHACHA20-Poly1305)
var ct = EnvelopeCipher.Encrypt(key32, data, CipherSuiteType.CHACHA20_POLY1305, aad);

// Stream/CTR example (CHACHA20)
var ct2 = EnvelopeCipher.Encrypt(key32, data, CipherSuiteType.CHACHA20);

remarks.para:
This formatter relies on FormatterProvider to resolve formatters
for both key and value types, supporting primitives, enums, structs,
classes, and nullable types automatically.
